// meta-ads-nightly — CHỈ Meta Marketing API. Kéo CHI TIÊU (spend) → Bronze + POST /api/ingest/ads.
// TÁCH RIÊNG khỏi TikTok có chủ đích: 2 API khác nhau, token khác nhau, kiểu lỗi khác nhau.
//
// BẤT BIẾN #2: CHỈ lấy `spend`. TUYỆT ĐỐI không kéo conversion value / purchase_roas / GMV —
// doanh thu chỉ đến từ Pancake, lấy 2 nguồn là đếm 2 lần cùng một giao dịch.
//
// ⚠️ VAT — BÀI HỌC TỪ TIKTOK (2026-07-14): `spend` của sàn là số CHƯA THUẾ. Với TikTok ta lấy được
// hoá đơn thật (subtotal + tax = amount) nên tính được VAT chính xác. META KHÔNG CÓ API HOÁ ĐƠN cho
// tài khoản trả THẺ (shop đang trả Mastercard) ⇒ buộc phải nhân hệ số VAT khai tay.
// ĐÃ CHỐT: VAT Facebook = 10% (chủ shop xác nhận 2026-07-14; khớp TikTok đo thật cũng 10%).
// Guard chỉ bắt `vatRate` RỖNG hoặc ngoài dải hợp lý ⇒ DỪNG. ĐỪNG đọc thành "quên đổi thuế suất
// thì workflow kêu to": nhà nước đổi 10% → 8% mà không ai sửa hằng này thì `0.10` vẫn hợp lệ, guard
// im lặng và mọi dòng trong cửa sổ được ghi bằng suất SAI. Không có gì tự phát hiện — đây là lý do
// mọi lượt backfill phải tự kiểm điều kiện VAT trước khi chạy (xem khối "Cần backfill" bên dưới).
//
// ⚠️ TOKEN NÀY KHÔNG TỰ GIA HẠN ĐƯỢC — ĐO THẬT 2026-07-14: gọi `fb_exchange_token` trên token đang
// sống trả về hạn Y HỆT (không nhúc nhích). Đồng hồ 60 ngày tính từ lúc chủ shop bấm "Generate" ở
// Graph API Explorer. ⇒ ~2 tháng/lần chủ shop PHẢI lấy token mới bằng tay rồi chạy
// `scripts/meta-ads-lay-token.ts`. (Muốn hết cảnh này: xin quyền Business Manager → System User
// token KHÔNG BAO GIỜ hết hạn. Chủ shop chưa xin được.)
//
// ⚠️ META CÓ **HAI** HẠN, cái NGẮN HƠN mới giết ta:
//   expires_at             — token hết hạn (60 ngày, token cá nhân dài hạn)
//   data_access_expires_at — quyền ĐỌC DỮ LIỆU hết hạn (90 ngày kể từ lần user bấm "Cho phép")
// Gia hạn (fb_exchange_token) chỉ đẩy được `expires_at`, KHÔNG reset data access — muốn reset thì
// chủ shop phải vào Graph API Explorer cấp quyền LẠI. Đo thật 2026-07-14: token còn 60 ngày nhưng
// data access chỉ còn 9 ngày.
/**
 * Khoá lấy từ node "Lấy khoá từ bảng Setting" (mỗi dòng = 1 cặp key/value của bảng `app."Setting"`).
 * Token Meta KHÔNG nằm ở đây — nó đi qua kho token của app vì còn phải ghi lại khi đổi token.
 */
const KHOA = Object.fromEntries($input.all().map((i) => [i.json.key, i.json.value]));
const KHOA_THIEU = ["n8nAppUrl","n8nIngestSecret","metaAdsAccountId"].filter((k) => !KHOA[k]);
if (KHOA_THIEU.length) {
  throw new Error(
    `THIẾU KHOÁ trong bảng app."Setting": ${KHOA_THIEU.join(", ")}. Thêm dòng key/value tương ứng rồi chạy lại.`
  );
}

const CONFIG = {
  appUrl: KHOA.n8nAppUrl,
  ingestSecret: KHOA.n8nIngestSecret,
  graphVersion: "v25.0",
  account: KHOA.metaAdsAccountId, // act_...
  // HỆ SỐ VAT = 0.10 (Facebook thu 10%, chủ shop xác nhận). Rỗng ⇒ workflow DỪNG khi có chi tiêu.
  vatRate: "0.10",
  // Cửa sổ mặc định 7 ngày (Meta chỉnh spend hồi tố vài ngày). Cần kéo rộng hơn thì thêm key
  // `metaAdsManualDays` (SỐ NGUYÊN 1–730) vào bảng Setting, ĐỪNG sửa số ở đây — xem ghi chú
  // "Cửa sổ ngày" bên dưới.
  nightlyDays: 7,
};

const GRAPH = "https://graph.facebook.com/" + CONFIG.graphVersion;
const DAY = 86400000;
const CHUNK = 500; // /api/ingest/ads chặn tối đa 2000 dòng mỗi lần POST
const NGUY_HIEM_NGAY = 7; // còn dưới ngần này ngày → gia hạn ngay
const CANH_BAO_NGAY = 14; // còn dưới ngần này ngày mà không gia hạn được → kêu to

const http = this.helpers.httpRequest;
const nowSec = () => Math.floor(Date.now() / 1000);
const logs = [];
const log = (m) => {
  logs.push(m);
  console.log("[meta-ads] " + m);
};

// Ngày theo GIỜ VN, KHÔNG theo TZ container n8n. en-CA ⇒ đúng định dạng "YYYY-MM-DD".
const vnFmt = new Intl.DateTimeFormat("en-CA", {
  timeZone: "Asia/Ho_Chi_Minh",
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
});
const vnDate = (ms) => vnFmt.format(new Date(ms));

// Cửa sổ ngày — MỘT nguồn duy nhất: key `metaAdsManualDays` trong bảng Setting ép cửa sổ cho MỌI
// lượt (theo lịch lẫn bấm tay); không có key thì dùng `nightlyDays`.
//
// Trước đây có nhánh "chạy theo lịch ⇒ 7 ngày, bấm tay ⇒ backfill 730 ngày" nhận diện bằng
// `$execution.mode === "trigger"`, kèm ghi chú khẳng định n8n không có mode nào tên "test".
// ĐO THẬT 26/07/2026, đo lại 01/08/2026 — biến này trong Code node CHỈ nhận 2 giá trị: lịch cron ⇒
// "production" (execution 104563), bấm tay ⇒ "test" (execution 104562). KHÔNG bao giờ là "trigger":
// đó là nhãn của REST /executions, khác hẳn biến trong Code node, và chính chỗ nhầm hai thứ đó đẻ ra
// lỗi này. Điều kiện cũ SAI với CẢ HAI chế độ ⇒ `lookbackDays: 7` là code chết, MỖI ĐÊM đều rơi vào
// nhánh backfill 730 ngày (log thật: "Kéo 9 lát 90 ngày: 2024-08-01 → 2026-07-31" ⇒ ghi lại toàn bộ
// dòng Expense từ 09/08/2024). Hậu quả chờ nổ: app tính `amount = spendExVat × (1 + vatRate)`, nên
// ngày nào đổi `vatRate` (thuế 10% → 8%) là ĐÊM ĐÓ 2 NĂM chi phí lịch sử bị viết lại ⇒ lợi nhuận mọi
// kỳ quá khứ nhảy số. Nay mặc định LUÔN là cửa sổ hẹp: mọi hiểu nhầm về chế độ chạy đều rơi về phía
// an toàn, và `execMode` cuối lượt in giá trị thô để lần sau khỏi phải suy đoán.
//
// Cần backfill: đặt `metaAdsManualDays` = N → chạy tay → TRẢ KEY VỀ 7 (hoặc xoá key).
//
// ⚠️ TRƯỚC KHI ĐẶT N: kiểm N ngày gần nhất có nằm TRỌN trong MỘT chế độ thuế suất không. Cả lượt
// chạy dùng đúng một `vatRate` (hằng khai tay ở CONFIG), nên một cửa sổ cắt qua ngày đổi thuế sẽ
// GHI LẠI phần lịch sử bên kia mốc bằng suất hiện hành — sai âm thầm, không có cảnh báo nào.
// Đặt thẳng 730 chỉ an toàn khi suốt 730 ngày qua thuế suất KHÔNG đổi.
//
// KHÔNG CÓ CÁCH BACKFILL XUYÊN MỐC ĐỔI THUẾ ở workflow này — đừng nghĩ ra mẹo "chia nhiều lượt,
// mỗi lượt một chế độ": `until` neo cứng vào HÔM QUA rồi trừ ngược ra `since`, không có tham số
// mốc kết thúc, nên mọi cửa sổ đều bám mép hiện tại. Lượt sau luôn phủ lại phần lượt trước vừa
// ghi, bằng `vatRate` đang khai — muốn lấy đúng phần cũ thì phải thêm mốc kết thúc, hoặc làm VAT
// theo ngày hiệu lực (việc còn treo, xem docs/lo-trinh-du-an.md).
//
// TRẦN 730 NGÀY — căn cứ đo được, không phải số bốc: dòng chi tiêu Meta xa nhất của shop là
// 08/08/2024 (đo bảng Expense trên prod 03/08/2026 ⇒ 725 ngày), nên 730 phủ TRỌN lịch sử,
// rộng hơn cũng không có dữ liệu để lấy. Chi phí gọi thì thoải mái: code chia lát 90 ngày
// ⇒ 730 ngày ≈ 9 lát (vài chục request), còn xa trần 3600s của runner. Trần này là để chặn
// NGƯỜI gõ nhầm, không phải để chặn API.
const MAX_MANUAL_DAYS = 730;

/**
 * Đọc số ngày ép từ một ô của bảng Setting. Trả 0 = KHÔNG ép (dùng `nightlyDays`).
 * CHỈ nhận số nguyên từ 1 đến `tran`; mọi giá trị khác ⇒ THROW.
 *
 * Vì sao không còn `Number(x) > 0` như bản trước: `"7.5"` cho mốc `since` lệch nửa ngày (sau này
 * rất khó truy ra vì sao thiếu/thừa một ngày), `"Infinity"` làm chính bước tính ngày NỔ giữa đêm
 * (đo 03/08/2026: workflow dùng `Intl.DateTimeFormat` ném `RangeError: Invalid time value`, workflow
 * dùng mốc epoch thì gửi lên API một cửa sổ vô nghĩa), `"100000"` bắn hàng nghìn request (chạm rate-limit và
 * trần 3600s của runner — N8N_RUNNERS_TASK_TIMEOUT), còn `"abc"` hay số âm thì rơi về mặc định
 * TRONG IM LẶNG: người vận hành đặt key xong tưởng đã backfill mà thực ra không.
 *
 * Vì sao THROW chứ không âm thầm về mặc định kèm cảnh báo: giá trị sai LUÔN do người vừa sửa bảng
 * Setting gõ nhầm — họ đang ở đó và thấy ngay execution FAILED. Hỏng một đêm KHÔNG mất dữ liệu:
 * cửa sổ thường trực là 7 ngày và Bronze dedupe theo hash nên lượt sau phủ lại phần thiếu.
 */
function soNgayCuaSo(key, giaTri, tran) {
  const s = String(giaTri === undefined || giaTri === null ? "" : giaTri).trim();
  if (s === "") return 0;
  if (!/^[0-9]+$/.test(s) || Number(s) < 1 || Number(s) > tran) {
    throw new Error(
      "Key " + key + ' = "' + s + '" KHÔNG hợp lệ — chỉ nhận SỐ NGUYÊN từ 1 đến ' + tran +
        " (không thập phân, không số âm, không chữ, không Infinity). Sửa lại ô đó trong bảng " +
        'app."Setting", hoặc XOÁ/để trống nó để quay về cửa sổ mặc định, rồi chạy lại.'
    );
  }
  return Number(s);
}

const soNgayEp = soNgayCuaSo("metaAdsManualDays", KHOA.metaAdsManualDays, MAX_MANUAL_DAYS);
const soNgay = soNgayEp > 0 ? soNgayEp : CONFIG.nightlyDays;
const now = Date.now();
const until = vnDate(now - DAY); // hôm qua (giờ VN)
const since = vnDate(now - soNgay * DAY);

let token = { accessToken: "", expireAt: 0, dataAccessExpireAt: 0 };

/** Hạn HIỆU LỰC = cái NGẮN HƠN trong 2 hạn của Meta. 0 = không hết hạn (System User token). */
function hanHieuLuc() {
  const a = token.expireAt || Infinity;
  const b = token.dataAccessExpireAt || Infinity;
  const m = Math.min(a, b);
  return m === Infinity ? 0 : m;
}
const conLaiNgay = (epoch) => (epoch ? Math.floor((epoch - nowSec()) / 86400) : Infinity);

/** Nạp token BỀN từ app. Kho rỗng (lần chạy đầu) ⇒ dùng hạt giống trong CONFIG. */
async function loadToken() {
  let res;
  try {
    res = await http({
      method: "GET",
      url: CONFIG.appUrl + "/api/ingest/meta-token",
      headers: { Authorization: "Bearer " + CONFIG.ingestSecret },
      json: true,
    });
  } catch (err) {
    throw new Error(
      "KHÔNG ĐỌC ĐƯỢC KHO TOKEN của app: " + ((err && err.message) || String(err)) +
        " — dừng TRƯỚC khi gia hạn để không đốt token khi chưa có chỗ lưu."
    );
  }
  if (res && res.accessToken) {
    token = {
      accessToken: res.accessToken,
      expireAt: Number(res.expireAt) || 0,
      dataAccessExpireAt: Number(res.dataAccessExpireAt) || 0,
    };
    log("Nạp token từ app · token còn " + conLaiNgay(token.expireAt) + " ngày · data access còn " +
      conLaiNgay(token.dataAccessExpireAt) + " ngày");
    return;
  }
  // Không còn token hạt giống trong workflow (bỏ cùng lúc chuyển khoá sang bảng Setting). Kho rỗng
  // nghĩa là chưa từng nạp token hoặc đã bị xoá — nói thẳng, đừng chạy tiếp rồi báo "success" rỗng.
  throw new Error(
    "KHO TOKEN META CỦA APP RỖNG. Lấy token mới bằng scripts/meta-ads-lay-token.ts rồi nạp qua " +
      "POST /api/ingest/meta-token (kèm cả hai hạn: token và quyền đọc dữ liệu)."
  );
}

/**
 * KIỂM HẠN — KHÔNG gia hạn (đã đo: không gia hạn được).
 *
 * Sắp hết hạn ⇒ cảnh báo. HẾT HẠN ⇒ THROW: chi phí quảng cáo ngừng chảy vào P&L mà không ai biết
 * chính là lỗi đã giết hệ cũ (token TikTok chết 12 ngày, workflow vẫn báo "success").
 */
function kiemHan() {
  const conToken = conLaiNgay(token.expireAt);
  const conData = conLaiNgay(token.dataAccessExpireAt);

  if (conToken !== Infinity && conToken <= 0) {
    throw new Error(
      "TOKEN META ĐÃ HẾT HẠN. KHÔNG tự gia hạn được (fb_exchange_token không đẩy được hạn — đã đo). " +
        "Chủ shop vào Graph API Explorer → Generate Access Token → Cho phép, rồi chạy " +
        "scripts/meta-ads-lay-token.ts \"<token mới>\"."
    );
  }
  if (conData !== Infinity && conData <= 0) {
    throw new Error(
      "QUYỀN ĐỌC DỮ LIỆU META ĐÃ HẾT HẠN — Meta từ chối mọi request dù token vẫn 'hợp lệ'. " +
        "Chủ shop phải CẤP QUYỀN LẠI ở Graph API Explorer."
    );
  }

  if (conToken !== Infinity && conToken < CANH_BAO_NGAY) {
    log("⚠️ TOKEN META còn " + conToken + " ngày. KHÔNG tự gia hạn được — chủ shop phải lấy token mới " +
      "ở Graph API Explorer. Hết hạn = chi phí quảng cáo ngừng vào P&L, lãi tự nhiên đẹp lên.");
  }
  if (conData !== Infinity && conData < CANH_BAO_NGAY) {
    log("⚠️ QUYỀN ĐỌC DỮ LIỆU còn " + conData + " ngày — cấp quyền lại ở Graph API Explorer.");
  }
}


/**
 * Meta SẬP (HTTP 500) khi xin cửa sổ dài tách theo NGÀY ở cấp campaign — không phải lỗi của ta,
 * là query quá nặng. Chia lát 90 ngày. (TikTok thì chặn cứng 30 ngày và báo lỗi tử tế hơn.)
 */
const MAX_SPAN_DAYS = 90;
function chiaLat(sinceStr, untilStr) {
  const lat = [];
  let s = new Date(sinceStr + "T00:00:00Z").getTime();
  const e = new Date(untilStr + "T00:00:00Z").getTime();
  while (s <= e) {
    const end = Math.min(s + (MAX_SPAN_DAYS - 1) * DAY, e);
    lat.push({ start: new Date(s).toISOString().slice(0, 10), end: new Date(end).toISOString().slice(0, 10) });
    s = end + DAY;
  }
  return lat;
}

/** Lỗi token của Meta: OAuthException, code 190/102/463, HTTP 401/403. Phải KÊU TO, không nuốt lặng. */
function laLoiToken(e) {
  const body = (e && e.response && e.response.body) || (e && e.error) || {};
  const err = (body && body.error) || {};
  const status = (e && (e.statusCode || e.httpCode)) || 0;
  const code = Number(err.code || 0);
  return code === 190 || code === 102 || code === 463 || err.type === "OAuthException" || status === 401 || status === 403;
}

/** GET TEXT THÔ (để land Bronze nguyên bản) + parse. Meta trả JSON phẳng, không có int64 trần. */
async function getInsights(lat, after) {
  const qs = {
    level: "campaign",
    // Xin ĐỦ field để Bronze giữ được bản gốc đầy đủ (kéo raw trước, hiểu sau). Vào P&L thì VẪN
    // CHỈ `spend` — số hiệu quả (impressions/clicks/reach/cpm/ctr) để dành cho phase marketing.
    //
    // TUYỆT ĐỐI KHÔNG xin `actions` / `action_values` / `purchase_roas`: đó là DOANH THU do Meta
    // quy kết. Doanh thu chỉ đến từ Pancake — lấy thêm ở đây là đếm 2 lần cùng một giao dịch.
    fields:
      "spend,campaign_id,campaign_name,objective,impressions,clicks,cpc,ctr,cpm,reach,frequency,account_currency,account_id",
    time_increment: 1, // BẮT BUỘC: tách theo NGÀY. Thiếu nó Meta gộp cả kỳ thành 1 dòng.
    time_range: JSON.stringify({ since: lat.start, until: lat.end }),
    limit: 500,
    access_token: token.accessToken,
  };
  if (after) qs.after = after;

  let text;
  try {
    text = await http({
      method: "GET",
      url: GRAPH + "/" + CONFIG.account + "/insights",
      qs: qs,
      json: false,
      encoding: "text", // giữ BẢN GỐC cho Bronze — không để n8n chuẩn hoá lại (đổi hash ⇒ dedupe hỏng)
    });
  } catch (err) {
    if (laLoiToken(err)) {
      throw new Error(
        "TOKEN META CHẾT: " + ((err && err.message) || String(err)) +
          " — lấy token mới ở Graph API Explorer (nếu quyền đọc dữ liệu hết hạn thì phải CẤP QUYỀN LẠI)."
      );
    }
    throw new Error("META insights lỗi: " + ((err && err.message) || String(err)));
  }
  if (typeof text !== "string") {
    throw new Error("n8n trả object, không phải TEXT thô — thiếu encoding:'text'.");
  }
  const j = JSON.parse(text);
  if (j.error) throw new Error("META insights lỗi: " + JSON.stringify(j.error));
  return { text: text, json: j };
}

/**
 * Land BẢN GỐC vào Bronze. Land hỏng KHÔNG giết cả lượt — Expense (số vào P&L) mới là bắt buộc.
 *
 * Đánh đổi phải biết: kể từ khi app dựng lại được chi tiêu quảng cáo TỪ kho thô, trang nào land
 * hỏng là trang đó mất khả năng dựng lại (sổ có số, kho thô không có gốc — app gọi là "ads mồ côi"
 * và đếm ở dialog xoá dữ liệu). Land raw KHÔNG tự ghi Expense: app chỉ dựng lại chi phí khi chủ shop
 * bấm "Dựng lại từ kho thô", nên hai đường vẫn không cộng dồn.
 */
async function landRaw(text) {
  try {
    const r = await http({
      method: "POST",
      url: CONFIG.appUrl + "/api/ingest/raw",
      json: true,
      headers: { Authorization: "Bearer " + CONFIG.ingestSecret },
      body: { stream: "meta/report", shopId: CONFIG.account, payload: text },
    });
    return (r && r.stats && Number(r.stats.landed)) || 0;
  } catch (e) {
    log("CẢNH BÁO: land raw hỏng: " + ((e && e.message) || String(e)));
    return 0;
  }
}

async function postRows(rows) {
  if (!rows.length) {
    log("0 dòng chi tiêu cho " + since + " → " + until + " (shop không chạy quảng cáo Meta kỳ này) — không POST.");
    return { source: "META", rows: 0, upserted: 0 };
  }
  let upserted = 0;
  for (let i = 0; i < rows.length; i += CHUNK) {
    const r = await http({
      method: "POST",
      url: CONFIG.appUrl + "/api/ingest/ads",
      headers: { Authorization: "Bearer " + CONFIG.ingestSecret },
      body: { source: "META", rows: rows.slice(i, i + CHUNK) },
      json: true,
    });
    upserted += (r && r.stats && Number(r.stats.rowsUpserted)) || 0;
  }
  log("META: " + rows.length + " dòng (" + since + " → " + until + "), app upsert " + upserted);
  return { source: "META", rows: rows.length, upserted: upserted };
}

// ---------- CHẠY ----------
await loadToken();
kiemHan();

const rows = [];
let landed = 0;
let currency = "";
let after = "";
const cacLat = chiaLat(since, until);
log("Cửa sổ " + soNgay + " ngày · kéo " + cacLat.length + " lát 90 ngày: " + since + " → " + until);

for (const lat of cacLat) {
for (let page = 0; page < 50; page++) {
  const res = await getInsights(lat, after);
  landed += await landRaw(res.text);

  for (const x of res.json.data || []) {
    if (x.account_currency) currency = String(x.account_currency);
    // M6: gửi CẢ dòng 0đ — campaign tắt/hết chi thì app hạ Expense về 0. Bỏ dòng 0đ ⇒ Expense giữ số cũ (chi phí thừa).
    rows.push({
      date: String(x.date_start || ""), // time_increment=1 ⇒ date_start = NGÀY (TZ ad account = VN)
      campaignId: String(x.campaign_id || ""),
      campaignName: x.campaign_name || "",
      spendExVat: Math.round(Number(x.spend || 0)), // CHƯA VAT, Int đồng — app tự nhân (1 + vatRate)
    });
  }
  const paging = res.json.paging || {};
  after = (paging.next && paging.cursors && paging.cursors.after) || "";
  if (!after) break;
  if (page === 49) throw new Error("META insights: quá 50 trang — DỪNG, nghi phân trang không dừng.");
}
after = ""; // cursor thuộc về LÁT vừa xong — mang sang lát sau là kéo nhầm dữ liệu
}

// Guard tiền tệ: ad account đổi sang tiền khác ⇒ chi phí sai ~26.000 lần ⇒ DỪNG.
if (rows.length) {
  if (!currency) throw new Error("META: không đọc được account_currency ⇒ không xác minh được VND, DỪNG.");
  if (currency !== "VND") {
    throw new Error("SAI TIỀN TỆ — META: ad account dùng '" + currency + "', không phải VND ⇒ DỪNG.");
  }
  const bad = rows.filter((r) => !/^\d{4}-\d{2}-\d{2}$/.test(r.date) || !r.campaignId);
  if (bad.length) {
    throw new Error("META: " + bad.length + " dòng thiếu date_start/campaign_id — DỪNG (mất time_increment=1?).");
  }
}

// VAT: `spend` của Meta là số CHƯA THUẾ. Chưa chốt hệ số mà đã có chi tiêu ⇒ DỪNG.
// Ghi thiếu 10% chi phí quảng cáo = lãi ảo cao hơn thật — đúng lỗi vừa phải sửa cho TikTok.
const VAT = CONFIG.vatRate === "" || CONFIG.vatRate === null ? null : Number(CONFIG.vatRate);
if (rows.length && (VAT === null || !isFinite(VAT))) {
  throw new Error(
    "META: có chi tiêu (" + rows.length + " dòng) nhưng CHƯA KHAI hệ số VAT. `spend` của Meta là số CHƯA " +
      "THUẾ, và Meta KHÔNG có API hoá đơn cho tài khoản trả thẻ ⇒ phải khai tay. Đọc 1 hoá đơn PDF " +
      "(Ads Manager → Billing) xem thuế 5% hay 10%, rồi điền CONFIG.vatRate = 0.05 / 0.10. " +
      "DỪNG để không ghi chi phí sai vào sổ."
  );
}
if (VAT !== null && (VAT < 0 || VAT > 0.2)) {
  throw new Error("META: hệ số VAT " + VAT + " vô lý (ngoài 0–0.2) ⇒ DỪNG.");
}

// HỢP ĐỒNG ADS: n8n KHÔNG nhân VAT nữa — chỉ gửi spendExVat (CHƯA thuế) + vatRate; APP nhân
// amount = round(spendExVat × (1 + vatRate)) vì app lo mọi logic tiền (TypeScript, có unit test).
const rowsRaVat = rows.map((r) => ({
  date: r.date,
  campaignId: r.campaignId,
  campaignName: r.campaignName,
  spendExVat: r.spendExVat,
  vatRate: VAT || 0, // hệ số khai tay, ĐÃ CHỐT 0.10
}));
const summary = [await postRows(rowsRaVat)];

// Đã ghi xong dữ liệu → giờ mới kêu to. Throw ở đây làm n8n đánh execution FAILED (chủ shop nhìn
// thấy), nhưng chi phí kỳ này VẪN vào sổ. Cảnh báo mà im lặng thì không ai đọc.
const conToken = conLaiNgay(token.expireAt);
if (conToken !== Infinity && conToken < NGUY_HIEM_NGAY) {
  throw new Error(
    "TOKEN META CÒN " + conToken + " NGÀY — sắp chết và KHÔNG tự gia hạn được. Dữ liệu kỳ này đã ghi " +
      "xong. Chủ shop: Graph API Explorer → Generate Access Token → Cho phép → chạy " +
      "scripts/meta-ads-lay-token.ts. (Hết hẳn cảnh này: xin quyền Business Manager, System User token " +
      "không bao giờ hết hạn.)"
  );
}

return [
  {
    json: {
      mode: soNgayEp > 0 ? `cửa sổ ép ${soNgayEp} ngày (key metaAdsManualDays)` : "mặc định (nightlyDays)",
      execMode: $execution.mode, // giá trị THẬT n8n trả cho biến này — ghi lại để khỏi phải đoán
      soNgay: soNgay,
      since: since,
      until: until,
      vat: VAT,
      landedBronze: landed,
      tokenConLaiNgay: conLaiNgay(hanHieuLuc()),
      dataAccessConLaiNgay: conLaiNgay(token.dataAccessExpireAt),
      summary: summary,
      logs: logs,
    },
  },
];
